//   fails_when=the filter is inverted/case-sensitive or the empty state is dropped; why_new=no test covers the search box; seam=none
// Value: protects=unknown near/city slugs render the generic "Discover what's near you" page instead of crashing;
//   fails_when=findCategory/findCity results are dereferenced without a guard; why_new=e2e uses only known slugs; seam=none
// Value: protects=legal pages (terms, privacy) hide the "Set location" button while product pages show it;
//   fails_when=the isLegal check is dropped or inverted; why_new=e2e checks legal status labels only; seam=none
import { cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import SitePage from './SitePage';

type Kind = 'page' | 'near' | 'city';
const show = (kind: Kind, slug: string) =>
  render(<SitePage kind={kind} slug={slug} go={vi.fn()} onChooseLocation={vi.fn()} />);

describe('SitePage', () => {
  afterEach(() => { cleanup(); localStorage.clear(); });

  it('DiscoveryGrid search filters categories and shows an empty state', () => {
    const go = vi.fn();
    render(<SitePage kind="page" slug="customers" go={go} onChooseLocation={vi.fn()} />);
    const search = screen.getByPlaceholderText('Search food and categories');
    expect(screen.getByRole('button', { name: 'Rice near me' })).toBeTruthy();

    fireEvent.change(search, { target: { value: 'RICE' } });
    expect(screen.getByRole('button', { name: 'Rice near me' })).toBeTruthy();
    expect(screen.queryByRole('button', { name: 'Pasta near me' })).toBeNull();
    fireEvent.click(screen.getByRole('button', { name: 'Rice near me' }));
    expect(go).toHaveBeenCalledWith('near/rice');

    fireEvent.change(search, { target: { value: 'zzz' } });
    expect(screen.getByText('No categories match “zzz”.')).toBeTruthy();
    expect(screen.queryByRole('button', { name: /near me|in my area/ })).toBeNull();

    fireEvent.change(search, { target: { value: '' } });
    expect(screen.getByRole('button', { name: 'Pasta near me' })).toBeTruthy();
  });

  it.each<[Kind, string]>([
    ['near', 'unknown-food'],
    ['city', 'atlantis'],
  ])('unknown %s slug "%s" shows the generic discovery page', (kind, slug) => {
    show(kind, slug);
    expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('Discover what’s near you');
    expect(screen.getByText('Set your delivery location to see what is available.')).toBeTruthy();
  });

  it.each([
    ['terms', false],
    ['privacy', false],
    ['vendors', true],
    ['about', true],
  ])('page/%s shows "Set location": %s', (slug, visible) => {
    show('page', slug);
    expect(screen.queryByRole('button', { name: 'Set location' }) !== null).toBe(visible);
  });
});
